B9/extract/zip_strip.probe:
r = ctx.extract(Label("//:arc.zip"), output = "z", strip_prefix = "pre")

listing = []
todo = [ctx.path("z")]
for _ in range(1000):
    if not todo:
        break
    p = todo.pop(0)
    for c in p.readdir():
        if c.is_dir:
            todo.append(c)
        else:
            listing.append(str(c).split("/z/", 1)[1] + "=" + ctx.read(c))

return json.encode(sorted(listing)) + "\n"

